import torch


def run(input):
    return torch.poisson(input)


def gen_inputs(ctx, device):
    import torch
    shape = tuple(ctx["input__shape"])
    dtype = getattr(torch, ctx["input__dtype"])
    if len(shape) == 2:
        # benchmark timing distribution: torch.rand
        inp = torch.rand(shape, dtype=dtype, device=device)
    else:
        # correctness distribution: constant rate lambda = 5.0
        inp = torch.full(shape, 5.0, dtype=dtype, device=device)
    return {"input": inp}


def valid(ref_outputs, sol_outputs, inputs, ctx):
    import torch
    sol = sol_outputs[0].detach().to("cpu").to(torch.float64)
    inp = inputs[0].detach().to("cpu").to(torch.float64)
    if bool((sol < 0).any().item()):
        return {"passed": False, "message": "poisson output has negative values", "metrics": {}}
    if not bool(torch.isfinite(sol).all().item()):
        return {"passed": False, "message": "poisson output has non-finite values", "metrics": {}}
    lam_min = float(inp.min().item())
    lam_max = float(inp.max().item())
    if lam_max == 0.0:
        ok = bool((sol == 0).all().item())
        return {"passed": ok, "message": "" if ok else "zero-rate output not all zero", "metrics": {}}
    if abs(lam_max - lam_min) < 1e-6:
        lam = lam_min
        mean = float(sol.mean().item())
        var = float(sol.var().item())
        if abs(lam - 5.0) < 1e-3:
            mean_tol, var_tol = 0.3, 0.5
        elif abs(lam - 50.0) < 1e-3:
            mean_tol, var_tol = 1.0, 5.0
        else:
            n = max(sol.numel(), 1)
            mean_tol = max(0.3, 6.0 * (lam / n) ** 0.5)
            var_tol = max(0.5, 8.0 * lam * (2.0 / n) ** 0.5)
        if abs(mean - lam) >= mean_tol:
            return {"passed": False, "message": f"mean {mean} deviates from lam {lam}", "metrics": {"mean": mean, "var": var}}
        if abs(var - lam) >= var_tol:
            return {"passed": False, "message": f"var {var} deviates from lam {lam}", "metrics": {"mean": mean, "var": var}}
        return {"passed": True, "message": "", "metrics": {"mean": mean, "var": var}}
    return {"passed": True, "message": "", "metrics": {}}
